<template>
  <PageShell title="质量管理" description="把来料、过程、成品和库存检验纳入同一条可追溯的质量闭环。">
    <template #actions>
      <button class="button button-ghost" @click="load">↻ 刷新</button>
      <button v-if="tab === 'plans'" class="button button-primary" @click="openNewPlan">+ 新建检验计划</button>
      <button v-if="tab === 'lots'" class="button button-primary" @click="openNewLot">+ 创建检验批</button>
      <button v-if="tab === 'supplier-evaluation'" class="button button-primary" @click="openNewSupplierEvaluation">+ 新建供应商考评</button>
      <button v-if="tab === 'avl'" class="button button-primary" @click="openNewAvl">+ 新增 AVL</button>
      <button v-if="tab === 'ipqc'" class="button button-primary" @click="openNewIpqc">+ 创建 IPQC 巡检</button>
      <button v-if="tab === 'nonconformance'" class="button button-primary" @click="openNewNc">+ 登记不合格</button>
    </template>

    <div class="subnav">
      <button v-for="item in tabs" :key="item.key" :class="['subnav-item', { active: tab === item.key }]" @click="switchTab(item.key)">{{ item.label }}</button>
    </div>

    <div v-if="tab === 'overview'" class="quality-overview">
      <div class="quality-kpis">
        <div class="quality-kpi"><span>待检验批</span><strong>{{ summary.pendingLots || 0 }}</strong><small>等待开始或完成检验</small></div>
        <div class="quality-kpi warning"><span>检验失败</span><strong>{{ summary.failedLots || 0 }}</strong><small>需要隔离和处置</small></div>
        <div class="quality-kpi danger"><span>未关闭不合格</span><strong>{{ summary.openNonconformances || 0 }}</strong><small>包含整改中的记录</small></div>
        <div class="quality-kpi success"><span>近 30 天合格率</span><strong>{{ summary.last30DaysPassRate || 0 }}%</strong><small>{{ summary.last30DaysLots || 0 }} 个检验批</small></div>
      </div>
      <div class="quality-grid">
        <div class="panel"><div class="panel-heading"><div><h3>检验类型分布</h3><p>按最近 30 天检验批和状态统计</p></div><span class="quality-badge">QMS</span></div><div v-if="typeRows.length" class="type-list"><div v-for="row in typeRows" :key="`${row.type}-${row.status}`" class="type-row"><div><b>{{ typeLabel(row.type) }}</b><small>{{ statusLabel(row.status) }}</small></div><div class="type-progress"><i :style="{ width: `${typePercent(row.count)}%` }"></i></div><strong>{{ row.count }}</strong></div></div><div v-else class="empty-operation">暂无近 30 天检验数据</div></div>
        <div class="panel"><div class="panel-heading"><div><h3>质量控制提示</h3><p>当前需要优先处理的质量事项</p></div></div><div class="quality-alerts"><div><span class="alert-mark orange">!</span><p><b>{{ summary.failedLots || 0 }} 个失败检验批</b><small>请在检验批详情中完成隔离与处置</small></p></div><div><span class="alert-mark red">!</span><p><b>{{ summary.openNonconformances || 0 }} 个不合格未关闭</b><small>需要补充根因、措施并关闭记录</small></p></div><div><span class="alert-mark blue">↗</span><p><b>{{ summary.overdueActions || 0 }} 个整改逾期</b><small>检查责任人和承诺完成日期</small></p></div></div></div>
      </div>
      <div class="quality-domain-grid"><button class="quality-domain-card" @click="switchTab('supplier-evaluation')"><span class="domain-icon green">✓</span><span><b>供应商考评</b><small>{{ summary.pendingSupplierEvaluations || 0 }} 条待提交 / 待审核</small></span><i>→</i></button><button class="quality-domain-card" @click="switchTab('avl')"><span class="domain-icon purple">AVL</span><span><b>质量 AVL</b><small>{{ summary.pendingAvl || 0 }} 条待认可关系</small></span><i>→</i></button><button class="quality-domain-card" @click="switchTab('ipqc')"><span class="domain-icon blue">IP</span><span><b>产线 IPQC</b><small>{{ summary.openIpqc || 0 }} 条现场巡检待处理</small></span><i>→</i></button></div>
      <div class="panel"><div class="panel-heading"><div><h3>最近检验批</h3><p>点击记录可直接录入检验结果</p></div><button class="text-button" @click="switchTab('lots')">查看全部 →</button></div><DataTable :columns="lotColumns" :rows="recentLots"><template #actions="{ row }"><button class="table-action" @click="openLot(row)">检验详情</button></template></DataTable></div>
    </div>

    <div v-else-if="tab === 'plans'" class="panel">
      <div class="filter-row"><input v-model="planKeyword" placeholder="搜索计划编码 / 物料编码 / 名称" @keyup.enter="load" /><select v-model="planStatus" @change="load"><option value="">全部状态</option><option value="DRAFT">草稿</option><option value="RELEASED">已发布</option><option value="OBSOLETE">已作废</option></select><button class="button button-ghost" @click="load">筛选</button><span class="filter-spacer"></span><span class="filter-note">{{ plans.length }} 条计划</span></div>
      <DataTable :columns="planColumns" :rows="plans"><template #actions="{ row }"><button class="table-action" @click="editPlan(row)">编辑</button><button v-if="row.status !== 'RELEASED'" class="table-action" @click="releasePlan(row)">发布</button></template></DataTable>
    </div>

    <div v-else-if="tab === 'lots'" class="panel">
      <div class="filter-row"><input v-model="lotKeyword" placeholder="搜索检验批 / 物料 / 批次" @keyup.enter="load" /><select v-model="lotStatus" @change="load"><option value="">全部状态</option><option value="PENDING">待检</option><option value="IN_PROGRESS">检验中</option><option value="PASSED">合格</option><option value="FAILED">不合格</option></select><select v-model="lotType" @change="load"><option value="">全部类型</option><option value="INCOMING">来料</option><option value="PROCESS">过程</option><option value="FINAL">成品</option><option value="STOCK">库存</option></select><button class="button button-ghost" @click="load">筛选</button><span class="filter-spacer"></span><span class="filter-note">{{ lots.length }} 个检验批</span></div>
      <DataTable :columns="lotColumns" :rows="lots"><template #actions="{ row }"><button class="table-action" @click="openLot(row)">结果录入</button></template></DataTable>
    </div>

    <div v-else-if="tab === 'supplier-evaluation'" class="panel">
      <div class="filter-row"><input v-model="supplierEvaluationKeyword" placeholder="搜索考评单 / 供应商" @keyup.enter="load" /><select v-model="supplierEvaluationStatus" @change="load"><option value="">全部状态</option><option value="DRAFT">草稿</option><option value="SUBMITTED">已提交</option></select><button class="button button-ghost" @click="load">筛选</button><span class="filter-spacer"></span><span class="filter-note">{{ supplierEvaluations.length }} 条考评</span></div>
      <div class="quality-module-tip"><span class="quality-module-icon">✓</span><div><b>供应商考评闭环</b><small>按交付、质量、服务、价格四项评分，自动计算加权总分和 A/B/C/D 等级。</small></div></div>
      <DataTable :columns="supplierEvaluationColumns" :rows="supplierEvaluations"><template #actions="{ row }"><button class="table-action" @click="editSupplierEvaluation(row)">编辑</button><button v-if="row.status === 'DRAFT'" class="table-action" @click="submitSupplierEvaluation(row)">提交</button></template></DataTable>
    </div>

    <div v-else-if="tab === 'avl'" class="panel">
      <div class="filter-row"><input v-model="avlKeyword" placeholder="搜索物料 / 供应商 / 供应商料号" @keyup.enter="load" /><select v-model="avlStatus" @change="load"><option value="">全部状态</option><option value="PENDING">待审核</option><option value="APPROVED">已认可</option><option value="SUSPENDED">已暂停</option><option value="EXPIRED">已过期</option></select><button class="button button-ghost" @click="load">筛选</button><span class="filter-spacer"></span><span class="filter-note">{{ avlEntries.length }} 条 AVL</span></div>
      <div class="quality-module-tip"><span class="quality-module-icon purple">AVL</span><div><b>Approved Vendor List · 质量认可清单</b><small>只允许已认可的物料—供应商组合进入采购和来料检验协同。</small></div></div>
      <DataTable :columns="avlColumns" :rows="avlEntries"><template #actions="{ row }"><button v-if="row.approval_status !== 'APPROVED'" class="table-action" @click="updateAvlStatus(row, 'APPROVED')">认可</button><button v-if="row.approval_status === 'APPROVED'" class="table-action danger" @click="updateAvlStatus(row, 'SUSPENDED')">暂停</button><button v-if="row.approval_status !== 'APPROVED'" class="table-action" @click="editAvl(row)">编辑</button></template></DataTable>
    </div>

    <div v-else-if="tab === 'ipqc'" class="panel">
      <div class="filter-row"><input v-model="ipqcKeyword" placeholder="搜索 IPQC / 工单 / 产品 / 批次" @keyup.enter="load" /><input v-model="ipqcLineCode" placeholder="产线编码" @keyup.enter="load" /><select v-model="ipqcStatus" @change="load"><option value="">全部状态</option><option value="PENDING">待巡检</option><option value="IN_PROGRESS">巡检中</option><option value="PASSED">合格</option><option value="FAILED">不合格</option><option value="CLOSED">已关闭</option></select><button class="button button-ghost" @click="load">筛选</button><span class="filter-spacer"></span><span class="filter-note">{{ ipqcRecords.length }} 条巡检</span></div>
      <div class="ipqc-summary"><div><span>待处理</span><b>{{ ipqcRecords.filter(item => ['PENDING', 'IN_PROGRESS'].includes(item.status)).length }}</b></div><div><span>不合格</span><b class="text-danger">{{ ipqcRecords.filter(item => item.status === 'FAILED').length }}</b></div><div><span>今日巡检</span><b>{{ ipqcRecords.filter(item => String(item.created_at || '').slice(0, 10) === new Date().toISOString().slice(0, 10)).length }}</b></div><div><span>覆盖产线</span><b>{{ new Set(ipqcRecords.map(item => item.line_code)).size }}</b></div></div>
      <DataTable :columns="ipqcColumns" :rows="ipqcRecords"><template #actions="{ row }"><button class="table-action" @click="openIpqc(row)">结果录入</button></template></DataTable>
    </div>

    <div v-else class="panel">
      <div class="filter-row"><input v-model="ncKeyword" placeholder="搜索不合格单 / 物料 / 缺陷" @keyup.enter="load" /><select v-model="ncStatus" @change="load"><option value="">全部状态</option><option value="OPEN">待处置</option><option value="CONTAINED">已隔离</option><option value="CLOSED">已关闭</option></select><button class="button button-ghost" @click="load">筛选</button><span class="filter-spacer"></span><span class="filter-note">{{ nonconformances.length }} 条记录</span></div>
      <DataTable :columns="ncColumns" :rows="nonconformances"><template #actions="{ row }"><button v-if="row.status !== 'CLOSED'" class="table-action" @click="openNc(row, 'disposition')">处置</button><button v-if="row.status !== 'CLOSED'" class="table-action" @click="openNc(row, 'action')">整改</button><button v-if="row.status !== 'CLOSED'" class="table-action" @click="openNc(row, 'close')">关闭</button></template></DataTable>
    </div>

    <div v-if="showPlanModal" class="modal-backdrop" @click.self="showPlanModal = false"><div class="modal modal-wide"><div class="modal-heading"><h3>{{ planForm.id ? '编辑检验计划' : '新建检验计划' }}</h3><button @click="showPlanModal = false">×</button></div><div class="form-grid"><label>计划编码<input v-model="planForm.planCode" placeholder="IQC-MOTOR-V1" /></label><label>计划名称<input v-model="planForm.planName" placeholder="电机来料检验" /></label><label>检验类型<select v-model="planForm.inspectionType"><option value="INCOMING">来料检验</option><option value="PROCESS">过程检验</option><option value="FINAL">成品检验</option><option value="STOCK">库存检验</option></select></label><label>适用物料<input v-model="planForm.materialCode" placeholder="留空表示通用" /></label><label>版本<input v-model="planForm.version" placeholder="V1" /></label><label>状态<select v-model="planForm.status"><option value="DRAFT">草稿</option><option value="RELEASED">已发布</option><option value="OBSOLETE">已作废</option></select></label></div><div class="item-heading"><div><b>检验项目</b><small>定量项目按上下限自动判定，定性项目按合格/不合格判定</small></div><button class="text-button" @click="addPlanItem">+ 添加项目</button></div><div class="plan-item" v-for="(item, index) in planForm.items" :key="index"><input v-model="item.characteristicCode" placeholder="特性编码" /><input v-model="item.characteristicName" placeholder="特性名称" /><select v-model="item.resultType"><option value="QUALITATIVE">定性</option><option value="QUANTITATIVE">定量</option></select><input v-model="item.standardText" placeholder="标准 / 说明" /><input v-if="item.resultType === 'QUANTITATIVE'" v-model="item.lowerLimit" type="number" placeholder="下限" /><input v-if="item.resultType === 'QUANTITATIVE'" v-model="item.upperLimit" type="number" placeholder="上限" /><button class="remove-item" @click="removePlanItem(index)">×</button></div><div class="modal-actions"><button class="button button-ghost" @click="showPlanModal = false">取消</button><button class="button button-primary" @click="savePlan">保存计划</button></div></div></div>

    <div v-if="showLotModal" class="modal-backdrop" @click.self="showLotModal = false"><div class="modal"><div class="modal-heading"><h3>创建检验批</h3><button @click="showLotModal = false">×</button></div><label>检验类型<select v-model="lotForm.inspectionType"><option value="INCOMING">来料检验</option><option value="PROCESS">过程检验</option><option value="FINAL">成品检验</option><option value="STOCK">库存检验</option></select></label><label>检验计划<select v-model="lotForm.planId"><option value="">自动匹配已发布计划</option><option v-for="plan in releasedPlans" :key="plan.id" :value="plan.id">{{ plan.plan_code }} · {{ plan.plan_name }}</option></select></label><label>物料编码<input v-model="lotForm.materialCode" placeholder="RM-MOTOR-001" /></label><label>物料名称<input v-model="lotForm.materialName" placeholder="物料名称" /></label><label>批次号<input v-model="lotForm.batchNo" placeholder="B20260819001" /></label><label>样本数量<input v-model="lotForm.sampleQty" type="number" min="1" /></label><label>来源单号<input v-model="lotForm.sourceDocNo" placeholder="收料单 / 工单号" /></label><div class="modal-actions"><button class="button button-ghost" @click="showLotModal = false">取消</button><button class="button button-primary" @click="saveLot">创建检验批</button></div></div></div>

    <div v-if="detail" class="modal-backdrop" @click.self="detail = null"><div class="modal modal-wide"><div class="modal-heading"><div><h3>{{ detail.lot_no }}</h3><small class="modal-subtitle">{{ detail.material_code }} · {{ typeLabel(detail.inspection_type) }} · {{ statusLabel(detail.status) }}</small></div><button @click="detail = null">×</button></div><div class="detail-strip"><span>检验计划 <b>{{ detail.plan_code || '未匹配' }}</b></span><span>批次 <b>{{ detail.batch_no || '-' }}</b></span><span>样本数 <b>{{ detail.sample_qty || 0 }}</b></span><span>已检 <b>{{ detail.inspected_qty || 0 }}</b></span></div><div class="result-list"><div v-for="item in resultDraft" :key="item.item_id" class="result-row"><div class="result-name"><b>{{ item.characteristic_name }}</b><small>{{ item.characteristic_code }} · {{ item.result_type === 'QUANTITATIVE' ? `${item.lower_limit ?? '-'} ~ ${item.upper_limit ?? '-'} ${item.unit || ''}` : item.standard_text || '按标准判定' }}</small></div><input v-if="item.result_type === 'QUANTITATIVE'" v-model="item.resultValue" type="number" placeholder="录入数值" /><select v-else v-model="item.resultStatus"><option value="">未判定</option><option value="PASS">合格</option><option value="FAIL">不合格</option></select><span :class="['result-status', `result-${String(item.result_status || item.resultStatus || 'PENDING').toLowerCase()}`]">{{ statusLabel(item.result_status || item.resultStatus || 'PENDING') }}</span></div><div v-if="!resultDraft.length" class="empty-operation">当前检验批没有匹配到检验项目，请先配置检验计划。</div></div><div class="modal-actions"><button v-if="detail.status === 'PENDING'" class="button button-ghost" @click="startLot">开始检验</button><button v-if="detail.status === 'IN_PROGRESS' || detail.status === 'PENDING'" class="button button-ghost" @click="saveResults">保存结果</button><button v-if="detail.status === 'IN_PROGRESS' || detail.status === 'PENDING'" class="button button-primary" @click="completeLot">完成判定</button></div></div></div>

    <div v-if="showNcModal" class="modal-backdrop" @click.self="showNcModal = false"><div class="modal"><div class="modal-heading"><h3>{{ ncModeLabel }}</h3><button @click="showNcModal = false">×</button></div><template v-if="ncMode === 'create'"><label>物料编码<input v-model="ncEditor.materialCode" placeholder="物料编码" /></label><label>批次号<input v-model="ncEditor.batchNo" placeholder="批次号" /></label><label>缺陷编码<input v-model="ncEditor.defectCode" placeholder="DIMENSION_OUT" /></label><label>缺陷名称<input v-model="ncEditor.defectName" placeholder="尺寸超差" /></label><label>严重等级<select v-model="ncEditor.severity"><option value="MINOR">一般</option><option value="MAJOR">重大</option><option value="CRITICAL">严重</option></select></label></template><template v-else-if="ncMode === 'disposition'"><div class="selected-record">{{ ncEditor.ncNo }} · {{ ncEditor.materialCode }} · {{ ncEditor.defectName }}</div><label>处置方式<select v-model="ncEditor.disposition"><option value="HOLD">隔离待判</option><option value="REWORK">返工</option><option value="SCRAP">报废</option><option value="RETURN">退供应商</option><option value="USE_AS_IS">让步接收</option></select></label><label>隔离 / 处置说明<textarea v-model="ncEditor.containmentAction" placeholder="说明隔离范围和处理动作"></textarea></label><label>责任人<input v-model="ncEditor.ownerCode" placeholder="质量或责任部门" /></label></template><template v-else-if="ncMode === 'action'"><div class="selected-record">{{ ncEditor.ncNo }} · 整改措施</div><label>措施描述<textarea v-model="ncEditor.actionDescription" placeholder="填写纠正或预防措施"></textarea></label><label>责任人<input v-model="ncEditor.ownerCode" placeholder="责任人编码" /></label><div v-if="ncActions.length" class="action-list"><div v-for="action in ncActions" :key="action.id"><span>{{ action.action_description }}</span><small>{{ action.status === 'CLOSED' ? '已完成' : '待完成' }}</small><button v-if="action.status !== 'CLOSED'" class="table-action" @click="completeAction(action)">完成</button></div></div></template><template v-else><div class="selected-record">{{ ncEditor.ncNo }} · 关闭前必须完成根因和措施</div><label>根因分析<textarea v-model="ncEditor.rootCause" placeholder="为什么发生"></textarea></label><label>纠正预防措施<textarea v-model="ncEditor.correctiveAction" placeholder="如何防止再次发生"></textarea></label></template><div class="modal-actions"><button class="button button-ghost" @click="showNcModal = false">取消</button><button class="button button-primary" @click="saveNc">保存</button></div></div></div>

    <div v-if="showSupplierEvaluationModal" class="modal-backdrop" @click.self="showSupplierEvaluationModal = false"><div class="modal modal-wide"><div class="modal-heading"><div><h3>{{ supplierEvaluationForm.id ? '编辑供应商考评' : '新建供应商考评' }}</h3><small class="modal-subtitle">四项评分按 25% / 40% / 15% / 20% 加权</small></div><button @click="showSupplierEvaluationModal = false">×</button></div><div class="form-grid"><label>供应商编码<input v-model="supplierEvaluationForm.supplierCode" placeholder="SUP-001" /></label><label>供应商名称<input v-model="supplierEvaluationForm.supplierName" placeholder="东莞精工电子" /></label><label>考评周期<input v-model="supplierEvaluationForm.evaluationPeriod" placeholder="2026-Q3" /></label><label>考评日期<input v-model="supplierEvaluationForm.evaluatedAt" type="date" /></label><label>交付评分<input v-model="supplierEvaluationForm.deliveryScore" type="number" min="0" max="100" /></label><label>质量评分<input v-model="supplierEvaluationForm.qualityScore" type="number" min="0" max="100" /></label><label>服务评分<input v-model="supplierEvaluationForm.serviceScore" type="number" min="0" max="100" /></label><label>价格评分<input v-model="supplierEvaluationForm.priceScore" type="number" min="0" max="100" /></label><label>责任人<input v-model="supplierEvaluationForm.ownerCode" placeholder="quality" /></label></div><label>备注<textarea v-model="supplierEvaluationForm.remark" placeholder="补充交付、质量异常或整改情况"></textarea></label><div class="modal-actions"><button class="button button-ghost" @click="showSupplierEvaluationModal = false">取消</button><button class="button button-primary" @click="saveSupplierEvaluation">保存考评</button></div></div></div>

    <div v-if="showAvlModal" class="modal-backdrop" @click.self="showAvlModal = false"><div class="modal modal-wide"><div class="modal-heading"><div><h3>{{ avlForm.id ? '编辑 AVL' : '新增 AVL' }}</h3><small class="modal-subtitle">维护物料与供应商的质量认可关系</small></div><button @click="showAvlModal = false">×</button></div><div class="form-grid"><label>物料编码<input v-model="avlForm.materialCode" placeholder="RM-MOTOR-001" /></label><label>物料名称<input v-model="avlForm.materialName" placeholder="无刷电机" /></label><label>供应商编码<input v-model="avlForm.supplierCode" placeholder="SUP-001" /></label><label>供应商名称<input v-model="avlForm.supplierName" placeholder="东莞精工电子" /></label><label>供应商料号<input v-model="avlForm.supplierPartNo" placeholder="MTR-2208" /></label><label>认可状态<select v-model="avlForm.approvalStatus"><option value="PENDING">待审核</option><option value="APPROVED">已认可</option><option value="SUSPENDED">已暂停</option></select></label><label>有效期起<input v-model="avlForm.validFrom" type="date" /></label><label>有效期止<input v-model="avlForm.validTo" type="date" /></label><label>最近考评得分<input v-model="avlForm.lastEvaluationScore" type="number" min="0" max="100" /></label></div><label>备注<textarea v-model="avlForm.remark" placeholder="认可范围、替代料或质量限制"></textarea></label><div class="modal-actions"><button class="button button-ghost" @click="showAvlModal = false">取消</button><button class="button button-primary" @click="saveAvl">保存 AVL</button></div></div></div>

    <div v-if="showIpqcModal" class="modal-backdrop" @click.self="showIpqcModal = false"><div class="modal modal-wide"><div class="modal-heading"><div><h3>创建产线 IPQC 巡检</h3><small class="modal-subtitle">建立首件与巡检记录，结果可在现场持续更新</small></div><button @click="showIpqcModal = false">×</button></div><div class="form-grid"><label>产线编码<input v-model="ipqcForm.lineCode" placeholder="LINE-01" /></label><label>工序名称<input v-model="ipqcForm.processName" placeholder="定子绕线" /></label><label>工序编码<input v-model="ipqcForm.processCode" placeholder="WINDING" /></label><label>工单号<input v-model="ipqcForm.workOrderNo" placeholder="WO-20260821-001" /></label><label>产品编码<input v-model="ipqcForm.productCode" placeholder="FG-MOTOR-001" /></label><label>产品名称<input v-model="ipqcForm.productName" placeholder="无刷电机总成" /></label><label>生产批次<input v-model="ipqcForm.batchNo" placeholder="B20260821001" /></label><label>抽检数量<input v-model="ipqcForm.sampleQty" type="number" min="1" /></label></div><label>巡检说明<textarea v-model="ipqcForm.remark" placeholder="首件、巡检频次或现场注意事项"></textarea></label><div class="modal-actions"><button class="button button-ghost" @click="showIpqcModal = false">取消</button><button class="button button-primary" @click="saveIpqc">创建巡检</button></div></div></div>

    <div v-if="showIpqcResultModal" class="modal-backdrop" @click.self="showIpqcResultModal = false"><div class="modal modal-wide"><div class="modal-heading"><div><h3>{{ ipqcEditor.ipqc_no }}</h3><small class="modal-subtitle">{{ ipqcEditor.line_code }} · {{ ipqcEditor.process_name }} · {{ ipqcEditor.work_order_no || '无工单' }}</small></div><button @click="showIpqcResultModal = false">×</button></div><div class="detail-strip"><span>产品 <b>{{ ipqcEditor.product_code || '-' }}</b></span><span>批次 <b>{{ ipqcEditor.batch_no || '-' }}</b></span><span>抽检数 <b>{{ ipqcEditor.sample_qty || 0 }}</b></span><span>当前状态 <b>{{ statusLabel(ipqcEditor.status) }}</b></span></div><div class="form-grid"><label>已检数量<input v-model="ipqcResultForm.inspectedQty" type="number" min="0" /></label><label>缺陷数量<input v-model="ipqcResultForm.defectQty" type="number" min="0" /></label><label>首件状态<select v-model="ipqcResultForm.firstPieceStatus"><option value="PENDING">未判定</option><option value="PASS">合格</option><option value="FAIL">不合格</option></select></label><label>巡检状态<select v-model="ipqcResultForm.status"><option value="IN_PROGRESS">巡检中</option><option value="PASSED">合格</option><option value="FAILED">不合格</option><option value="CLOSED">已关闭</option></select></label></div><label>结果备注<textarea v-model="ipqcResultForm.remark" placeholder="记录异常现象、处置和复判结论"></textarea></label><div class="modal-actions"><button class="button button-ghost" @click="showIpqcResultModal = false">取消</button><button class="button button-primary" @click="saveIpqcResult">保存结果</button></div></div></div>
  </PageShell>
</template>

<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import PageShell from '../components/PageShell.vue'
import DataTable from '../components/DataTable.vue'
import { request } from '../api'

function notify(message, type = 'error') { window.dispatchEvent(new CustomEvent('polaris:toast', { detail: { message, type } })) }

const route = useRoute(); const router = useRouter()
const tab = computed(() => route.params.tab || 'overview')
const tabs = [{ key: 'overview', label: '质量总览' }, { key: 'supplier-evaluation', label: '供应商考评' }, { key: 'avl', label: '质量 AVL' }, { key: 'plans', label: '检验计划' }, { key: 'lots', label: '检验批' }, { key: 'ipqc', label: '产线 IPQC' }, { key: 'nonconformance', label: '不合格与整改' }]
const summary = ref({}); const typeRows = ref([]); const recentLots = ref([]); const plans = ref([]); const lots = ref([]); const nonconformances = ref([]); const supplierEvaluations = ref([]); const avlEntries = ref([]); const ipqcRecords = ref([])
const planKeyword = ref(''); const planStatus = ref(''); const lotKeyword = ref(''); const lotStatus = ref(''); const lotType = ref(''); const ncKeyword = ref(''); const ncStatus = ref(''); const supplierEvaluationKeyword = ref(''); const supplierEvaluationStatus = ref(''); const avlKeyword = ref(''); const avlStatus = ref(''); const ipqcKeyword = ref(''); const ipqcStatus = ref(''); const ipqcLineCode = ref('')
const showPlanModal = ref(false); const showLotModal = ref(false); const showNcModal = ref(false); const showSupplierEvaluationModal = ref(false); const showAvlModal = ref(false); const showIpqcModal = ref(false); const showIpqcResultModal = ref(false); const detail = ref(null); const resultDraft = ref([]); const ncMode = ref('create'); const ncEditor = ref({}); const ncActions = ref([]); const ipqcEditor = ref({})
const planForm = ref({ planCode: '', planName: '', inspectionType: 'INCOMING', materialCode: '', version: 'V1', status: 'DRAFT', items: [] })
const lotForm = ref({ inspectionType: 'INCOMING', planId: '', materialCode: '', materialName: '', batchNo: '', sampleQty: 1, sourceDocNo: '' })
const supplierEvaluationForm = ref({ supplierCode: '', supplierName: '', evaluationPeriod: '', evaluatedAt: new Date().toISOString().slice(0, 10), deliveryScore: 0, qualityScore: 0, serviceScore: 0, priceScore: 0, ownerCode: '', remark: '' })
const avlForm = ref({ materialCode: '', materialName: '', supplierCode: '', supplierName: '', supplierPartNo: '', approvalStatus: 'PENDING', validFrom: '', validTo: '', lastEvaluationScore: '', remark: '' })
const ipqcForm = ref({ lineCode: '', processCode: '', processName: '', workOrderNo: '', productCode: '', productName: '', batchNo: '', sampleQty: 1, remark: '' })
const ipqcResultForm = ref({ inspectedQty: 0, defectQty: 0, firstPieceStatus: 'PENDING', status: 'IN_PROGRESS', remark: '' })
const planColumns = [{ key: 'plan_code', label: '计划编码' }, { key: 'plan_name', label: '计划名称' }, { key: 'inspection_type', label: '类型', format: typeLabel }, { key: 'material_code', label: '适用物料', format: value => value || '通用' }, { key: 'item_count', label: '检验项' }, { key: 'version', label: '版本' }, { key: 'status', label: '状态', status: true, format: statusLabel }]
const lotColumns = [{ key: 'lot_no', label: '检验批号' }, { key: 'inspection_type', label: '类型', format: typeLabel }, { key: 'material_code', label: '物料' }, { key: 'batch_no', label: '批次', format: value => value || '-' }, { key: 'sample_qty', label: '样本数' }, { key: 'status', label: '状态', status: true, format: statusLabel }, { key: 'created_at', label: '创建时间', format: formatDate }]
const ncColumns = [{ key: 'nc_no', label: '不合格单' }, { key: 'material_code', label: '物料' }, { key: 'batch_no', label: '批次', format: value => value || '-' }, { key: 'defect_name', label: '缺陷' }, { key: 'severity', label: '等级', format: severityLabel }, { key: 'disposition', label: '处置', format: dispositionLabel }, { key: 'status', label: '状态', status: true, format: statusLabel }, { key: 'created_at', label: '创建时间', format: formatDate }]
const supplierEvaluationColumns = [{ key: 'evaluation_no', label: '考评单号' }, { key: 'supplier_name', label: '供应商', format: (value, row) => `${value || '-'}${row.supplier_code ? ` · ${row.supplier_code}` : ''}` }, { key: 'evaluation_period', label: '考评周期' }, { key: 'delivery_score', label: '交付', format: scoreLabel }, { key: 'quality_score', label: '质量', format: scoreLabel }, { key: 'total_score', label: '总分', format: scoreLabel }, { key: 'grade', label: '等级', format: value => value || '-' }, { key: 'status', label: '状态', status: true, format: statusLabel }]
const avlColumns = [{ key: 'material_code', label: '物料编码', format: (value, row) => `${value || '-'}${row.material_name ? ` · ${row.material_name}` : ''}` }, { key: 'supplier_name', label: '供应商', format: (value, row) => `${value || '-'}${row.supplier_code ? ` · ${row.supplier_code}` : ''}` }, { key: 'supplier_part_no', label: '供应商料号', format: value => value || '-' }, { key: 'last_evaluation_score', label: '考评得分', format: scoreLabel }, { key: 'valid_to', label: '有效期至', format: value => value || '长期' }, { key: 'approval_status', label: '认可状态', status: true, format: statusLabel }]
const ipqcColumns = [{ key: 'ipqc_no', label: 'IPQC 单号' }, { key: 'line_code', label: '产线' }, { key: 'process_name', label: '工序' }, { key: 'work_order_no', label: '工单', format: value => value || '-' }, { key: 'product_code', label: '产品', format: value => value || '-' }, { key: 'sample_qty', label: '抽检数' }, { key: 'defect_qty', label: '缺陷数' }, { key: 'status', label: '状态', status: true, format: statusLabel }, { key: 'created_at', label: '创建时间', format: formatDate }]
const releasedPlans = computed(() => plans.value.filter(item => item.status === 'RELEASED'))
const ncModeLabel = computed(() => ({ create: '登记不合格', disposition: '不合格处置', action: '整改措施', close: '关闭不合格' }[ncMode.value]))

function switchTab(value) { router.push(`/quality/${value}`) }
function statusLabel(value) { return ({ DRAFT: '草稿', RELEASED: '已发布', OBSOLETE: '已作废', PENDING: '待检', IN_PROGRESS: '检验中', PASSED: '合格', FAILED: '不合格', CANCELLED: '已取消', OPEN: '待处置', CONTAINED: '已隔离', CLOSED: '已关闭', PASS: '合格', FAIL: '不合格', SUBMITTED: '已提交', APPROVED: '已认可', SUSPENDED: '已暂停', EXPIRED: '已过期' }[value] || value || '-') }
function typeLabel(value) { return ({ INCOMING: '来料', PROCESS: '过程', FINAL: '成品', STOCK: '库存' }[value] || value || '-') }
function severityLabel(value) { return ({ MINOR: '一般', MAJOR: '重大', CRITICAL: '严重' }[value] || value || '-') }
function dispositionLabel(value) { return ({ HOLD: '隔离待判', REWORK: '返工', SCRAP: '报废', RETURN: '退供应商', USE_AS_IS: '让步接收' }[value] || value || '未处置') }
function formatDate(value) { return value ? new Date(value).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '-' }
function scoreLabel(value) { return value === null || value === undefined || value === '' ? '-' : Number(value).toFixed(1) }
function typePercent(count) { const total = typeRows.value.reduce((sum, row) => sum + Number(row.count || 0), 0); return total ? Math.max(8, Math.round(Number(count || 0) * 100 / total)) : 0 }
function idOf(row) { return Number(row.id) }

async function load() {
  try {
    if (tab.value === 'overview') { const data = await request('/quality/summary'); summary.value = data; typeRows.value = data.byType || []; recentLots.value = await request('/quality/lots') }
    if (tab.value === 'plans') plans.value = await request(`/quality/plans?status=${encodeURIComponent(planStatus.value)}&keyword=${encodeURIComponent(planKeyword.value)}`)
    if (tab.value === 'lots') lots.value = await request(`/quality/lots?status=${encodeURIComponent(lotStatus.value)}&keyword=${encodeURIComponent(lotKeyword.value)}&inspectionType=${encodeURIComponent(lotType.value)}`)
    if (tab.value === 'supplier-evaluation') supplierEvaluations.value = await request(`/quality/supplier-evaluations?status=${encodeURIComponent(supplierEvaluationStatus.value)}&keyword=${encodeURIComponent(supplierEvaluationKeyword.value)}`)
    if (tab.value === 'avl') avlEntries.value = await request(`/quality/avl?status=${encodeURIComponent(avlStatus.value)}&keyword=${encodeURIComponent(avlKeyword.value)}`)
    if (tab.value === 'ipqc') ipqcRecords.value = await request(`/quality/ipqc?status=${encodeURIComponent(ipqcStatus.value)}&keyword=${encodeURIComponent(ipqcKeyword.value)}&lineCode=${encodeURIComponent(ipqcLineCode.value)}`)
    if (tab.value === 'nonconformance') nonconformances.value = await request(`/quality/nonconformances?status=${encodeURIComponent(ncStatus.value)}&keyword=${encodeURIComponent(ncKeyword.value)}`)
    if (tab.value !== 'plans' && !plans.value.length) plans.value = await request('/quality/plans')
  } catch (error) { notify(error.message) }
}

function openNewPlan() { planForm.value = { planCode: '', planName: '', inspectionType: 'INCOMING', materialCode: '', version: 'V1', status: 'DRAFT', items: [newPlanItem()] }; showPlanModal.value = true }
function newPlanItem() { return { characteristicCode: '', characteristicName: '', resultType: 'QUALITATIVE', standardText: '', lowerLimit: '', upperLimit: '', requiredFlag: true } }
function addPlanItem() { planForm.value.items.push(newPlanItem()) }
function removePlanItem(index) { if (planForm.value.items.length > 1) planForm.value.items.splice(index, 1) }
async function editPlan(row) { try { const data = await request(`/quality/plans/${idOf(row)}`); planForm.value = { id: data.id, planCode: data.plan_code, planName: data.plan_name, inspectionType: data.inspection_type, materialCode: data.material_code || '', version: data.version || 'V1', status: data.status, items: (data.items || []).map(item => ({ characteristicCode: item.characteristic_code, characteristicName: item.characteristic_name, resultType: item.result_type, standardText: item.standard_text || '', lowerLimit: item.lower_limit ?? '', upperLimit: item.upper_limit ?? '', requiredFlag: item.required_flag !== 0 })) }; showPlanModal.value = true } catch (error) { notify(error.message) } }
async function releasePlan(row) { try { const data = await request(`/quality/plans/${idOf(row)}`); await request(`/quality/plans/${idOf(row)}`, { method: 'PUT', body: JSON.stringify({ planCode: data.plan_code, planName: data.plan_name, inspectionType: data.inspection_type, materialCode: data.material_code, productCode: data.product_code, version: data.version, status: 'RELEASED', items: (data.items || []).map(item => ({ characteristicCode: item.characteristic_code, characteristicName: item.characteristic_name, resultType: item.result_type, standardText: item.standard_text, lowerLimit: item.lower_limit, upperLimit: item.upper_limit, unit: item.unit, requiredFlag: item.required_flag })) }) }); await load() } catch (error) { notify(error.message) } }
async function savePlan() { try { await request(planForm.value.id ? `/quality/plans/${planForm.value.id}` : '/quality/plans', { method: planForm.value.id ? 'PUT' : 'POST', body: JSON.stringify({ ...planForm.value, items: planForm.value.items.filter(item => item.characteristicCode && item.characteristicName) }) }); showPlanModal.value = false; await load() } catch (error) { notify(error.message) } }

function openNewLot() { lotForm.value = { inspectionType: 'INCOMING', planId: '', materialCode: '', materialName: '', batchNo: '', sampleQty: 1, sourceDocNo: '' }; showLotModal.value = true }
async function saveLot() { try { const payload = { ...lotForm.value, planId: lotForm.value.planId ? Number(lotForm.value.planId) : undefined, sampleQty: Number(lotForm.value.sampleQty) }; await request('/quality/lots', { method: 'POST', body: JSON.stringify(payload) }); showLotModal.value = false; await load() } catch (error) { notify(error.message) } }
async function openLot(row) { try { const data = await request(`/quality/lots/${idOf(row)}`); detail.value = data; resultDraft.value = (data.items || []).map(item => ({ ...item, resultValue: item.result_value ?? '', resultText: item.result_text ?? '', resultStatus: item.result_status === 'PENDING' ? '' : item.result_status })) } catch (error) { notify(error.message) } }
async function startLot() { try { detail.value = await request(`/quality/lots/${idOf(detail.value)}/start`, { method: 'POST' }); syncResults() } catch (error) { notify(error.message) } }
async function saveResults() { try { const data = await request(`/quality/lots/${idOf(detail.value)}/results`, { method: 'POST', body: JSON.stringify({ items: resultDraft.value.map(item => ({ itemId: item.item_id, resultValue: item.resultValue || undefined, resultText: item.resultStatus || item.resultText || undefined, resultStatus: item.resultStatus || undefined })) }) }); detail.value = data; syncResults(); notify('检验结果已保存', 'success') } catch (error) { notify(error.message) } }
async function completeLot() { if (!window.confirm('确认完成检验并生成最终质量判定吗？')) return; try { detail.value = await request(`/quality/lots/${idOf(detail.value)}/complete`, { method: 'POST' }); syncResults(); if (tab.value === 'lots') await load() } catch (error) { notify(error.message) } }
function syncResults() { resultDraft.value = (detail.value?.items || []).map(item => ({ ...item, resultValue: item.result_value ?? item.resultValue ?? '', resultText: item.result_text ?? item.resultText ?? '', resultStatus: item.result_status === 'PENDING' ? '' : item.result_status })) }

function openNewNc() { ncMode.value = 'create'; ncEditor.value = { materialCode: '', batchNo: '', defectCode: '', defectName: '', severity: 'MAJOR' }; ncActions.value = []; showNcModal.value = true }
async function openNc(row, mode) { ncMode.value = mode; ncEditor.value = { id: idOf(row), ncNo: row.nc_no, materialCode: row.material_code, batchNo: row.batch_no, defectName: row.defect_name, disposition: row.disposition || 'HOLD', containmentAction: row.containment_action || '', ownerCode: row.owner_code || '', rootCause: row.root_cause || '', correctiveAction: row.corrective_action || '', actionDescription: '' }; ncActions.value = mode === 'action' ? await request(`/quality/nonconformances/${idOf(row)}/actions`) : []; showNcModal.value = true }
async function saveNc() { try { if (ncMode.value === 'create') await request('/quality/nonconformances', { method: 'POST', body: JSON.stringify(ncEditor.value) }); if (ncMode.value === 'disposition') await request(`/quality/nonconformances/${ncEditor.value.id}/disposition`, { method: 'POST', body: JSON.stringify(ncEditor.value) }); if (ncMode.value === 'action') { await request(`/quality/nonconformances/${ncEditor.value.id}/actions`, { method: 'POST', body: JSON.stringify(ncEditor.value) }); ncEditor.value.actionDescription = ''; ncActions.value = await request(`/quality/nonconformances/${ncEditor.value.id}/actions`); return } if (ncMode.value === 'close') await request(`/quality/nonconformances/${ncEditor.value.id}/close`, { method: 'POST', body: JSON.stringify(ncEditor.value) }); showNcModal.value = false; await load() } catch (error) { notify(error.message) } }
async function completeAction(action) { try { await request(`/quality/actions/${action.id}/complete`, { method: 'POST' }); ncActions.value = await request(`/quality/nonconformances/${ncEditor.value.id}/actions`) } catch (error) { notify(error.message) } }

function openNewSupplierEvaluation() { supplierEvaluationForm.value = { supplierCode: '', supplierName: '', evaluationPeriod: new Date().toISOString().slice(0, 7), evaluatedAt: new Date().toISOString().slice(0, 10), deliveryScore: 0, qualityScore: 0, serviceScore: 0, priceScore: 0, ownerCode: '', remark: '' }; showSupplierEvaluationModal.value = true }
async function editSupplierEvaluation(row) { supplierEvaluationForm.value = { id: idOf(row), supplierCode: row.supplier_code, supplierName: row.supplier_name, evaluationPeriod: row.evaluation_period, evaluatedAt: row.evaluated_at || '', deliveryScore: row.delivery_score || 0, qualityScore: row.quality_score || 0, serviceScore: row.service_score || 0, priceScore: row.price_score || 0, ownerCode: row.owner_code || '', remark: row.remark || '' }; showSupplierEvaluationModal.value = true }
async function saveSupplierEvaluation() { try { await request(supplierEvaluationForm.value.id ? `/quality/supplier-evaluations/${supplierEvaluationForm.value.id}` : '/quality/supplier-evaluations', { method: supplierEvaluationForm.value.id ? 'PUT' : 'POST', body: JSON.stringify(supplierEvaluationForm.value) }); showSupplierEvaluationModal.value = false; await load() } catch (error) { notify(error.message) } }
async function submitSupplierEvaluation(row) { if (!window.confirm(`确认提交 ${row.evaluation_no} 吗？提交后将进入质量审核状态。`)) return; try { await request(`/quality/supplier-evaluations/${idOf(row)}/submit`, { method: 'POST' }); await load() } catch (error) { notify(error.message) } }

function openNewAvl() { avlForm.value = { materialCode: '', materialName: '', supplierCode: '', supplierName: '', supplierPartNo: '', approvalStatus: 'PENDING', validFrom: new Date().toISOString().slice(0, 10), validTo: '', lastEvaluationScore: '', remark: '' }; showAvlModal.value = true }
function editAvl(row) { avlForm.value = { id: idOf(row), materialCode: row.material_code, materialName: row.material_name || '', supplierCode: row.supplier_code, supplierName: row.supplier_name, supplierPartNo: row.supplier_part_no || '', approvalStatus: row.approval_status || 'PENDING', validFrom: row.valid_from || '', validTo: row.valid_to || '', lastEvaluationScore: row.last_evaluation_score ?? '', remark: row.remark || '' }; showAvlModal.value = true }
async function saveAvl() { try { await request(avlForm.value.id ? `/quality/avl/${avlForm.value.id}` : '/quality/avl', { method: avlForm.value.id ? 'PUT' : 'POST', body: JSON.stringify(avlForm.value) }); showAvlModal.value = false; await load() } catch (error) { notify(error.message) } }
async function updateAvlStatus(row, approvalStatus) { try { await request(`/quality/avl/${idOf(row)}/status`, { method: 'POST', body: JSON.stringify({ approvalStatus }) }); await load() } catch (error) { notify(error.message) } }

function openNewIpqc() { ipqcForm.value = { lineCode: '', processCode: '', processName: '', workOrderNo: '', productCode: '', productName: '', batchNo: '', sampleQty: 1, remark: '' }; showIpqcModal.value = true }
async function saveIpqc() { try { await request('/quality/ipqc', { method: 'POST', body: JSON.stringify({ ...ipqcForm.value, sampleQty: Number(ipqcForm.value.sampleQty) }) }); showIpqcModal.value = false; await load() } catch (error) { notify(error.message) } }
async function openIpqc(row) { try { ipqcEditor.value = await request(`/quality/ipqc/${idOf(row)}`); ipqcResultForm.value = { inspectedQty: ipqcEditor.value.inspected_qty || 0, defectQty: ipqcEditor.value.defect_qty || 0, firstPieceStatus: ipqcEditor.value.first_piece_status || 'PENDING', status: ['PASSED', 'FAILED', 'CLOSED'].includes(ipqcEditor.value.status) ? ipqcEditor.value.status : 'IN_PROGRESS', remark: ipqcEditor.value.remark || '' }; showIpqcResultModal.value = true } catch (error) { notify(error.message) } }
async function saveIpqcResult() { try { ipqcEditor.value = await request(`/quality/ipqc/${idOf(ipqcEditor.value)}/result`, { method: 'POST', body: JSON.stringify({ ...ipqcResultForm.value, inspectedQty: Number(ipqcResultForm.value.inspectedQty), defectQty: Number(ipqcResultForm.value.defectQty) }) }); showIpqcResultModal.value = false; await load() } catch (error) { notify(error.message) } }

onMounted(load)
watch(() => route.params.tab, load)
</script>

